import { makeReading as make, q, v } from './authoring.mjs';

export const readings = [
make('2級', 'arts-culture', 'A Song with Room for the Listener', [
  `Nora wrote a song for her school's autumn concert. It described someone standing at a station after a friend had left. Nora knew exactly who the friend was and why the journey mattered, but she did not put those details into the song. Instead, she described a cold bench, an unfinished cup of tea, and the sound of a departing train.`,
  `At the first rehearsal, her friend Ben asked whether the song was about moving to another country. A younger student thought it was about two people who had argued. Nora worried that she had failed to explain her story. She added a long verse telling the listener when the friendship began and what had happened before the departure.`,
  `The new verse answered the questions, but singing it felt awkward. The melody had to repeat several times to fit all the words. More importantly, Nora noticed that listeners now talked mostly about the events. Before the change, they had talked about moments in their own lives when they had wanted someone to stay. The extra details had made the story clearer while leaving less room for a personal response.`,
  `Nora removed most of the new verse. She kept one sentence that explained why the singer stayed on the platform, because without it the final action was confusing. At the concert, she did not introduce the song with its full background. Afterwards, Ben said it reminded him of saying goodbye to his brother. That was different from Nora's original experience, but she no longer treated the difference as a mistake. She had learned to distinguish information that helped listeners follow a song from information that merely made them share her exact interpretation.`,
], [
  q('detail', 'What did Nora initially leave out of her song?', ['The sound heard at the station.', 'The personal history behind the departure.', 'The place where the singer was waiting.', 'The objects around the singer.'], 1, '駅や物音などは描写しましたが、友人が誰で、なぜ旅が重要なのかという具体的な事情は入れませんでした。', 'p1', 'she did not put those details into the song'),
  q('inference', 'Why did Nora first add another verse?', ['She wanted to include a second singer.', 'She needed to make the concert last longer.', 'She hoped to remove all descriptions of the station.', 'She believed different interpretations showed that her story was unclear.'], 3, '別々の解釈を聞き、自分の物語をうまく説明できていないと不安になったためです。', 'p2', 'Nora worried that she had failed to explain her story'),
  q('detail', 'What did Nora notice after adding the verse?', ['Listeners focused more on the events than on their own experiences.', 'The melody became shorter and easier to sing.', 'Nobody could understand where the song took place.', 'Listeners all remembered the same family member.'], 0, '追加前は自分の体験を語っていた聴き手が、追加後は歌の出来事を中心に話すようになりました。', 'p3', 'listeners now talked mostly about the events'),
  q('main-idea', 'What did Nora learn about explaining a song?', ['Every listener should discover the writer’s complete history.', 'Removing every clear detail makes a song more effective.', 'Some clarity is useful without requiring one identical interpretation.', 'A song should change its meaning whenever anyone asks a question.'], 2, '筋を追うために必要な説明は残しつつ、全員に自分と同じ解釈を求める必要はないと学びました。', 'p4', 'distinguish information that helped listeners follow a song from information that merely made them share her exact interpretation'),
], [v('rehearsal', '本番に向けた練習・リハーサル'), v('interpretation', '解釈'), v('departure', '出発・旅立ち')]),

make('2級', 'sports', 'The Second Runner', [
  `Daniel was the fastest runner in his class over a short distance. When the class prepared for a relay race, he expected to run the final section. He imagined crossing the finish line while everyone cheered. His teacher instead placed him second. Daniel was disappointed and asked whether she had forgotten his result from the individual race.`,
  `The teacher explained that choosing a relay team involved more than comparing separate running times. Daniel could receive the baton smoothly from a slower runner and pass it accurately to the next person. Another student, Luis, ran well when he could see someone ahead and chase them. The teacher wanted Luis to finish and Daniel to help connect the middle of the team.`,
  `At first, Daniel practiced his own running more than the exchanges. During a practice race, he started too early and left the first runner struggling to reach him. They lost several seconds. Daniel's individual section was still quick, but the team's total time was worse. He realized that leaving sooner was not helpful if his teammate could not complete the pass.`,
  `Before the next practice, the two runners agreed on a clear starting signal. Daniel also asked the third runner where she preferred to receive the baton. Their coordination improved, and the team finished faster even though Daniel did not set a personal record. On race day, Luis crossed the line just behind the winning team. Daniel was disappointed about losing, but he could also name things they had done well. Later, he kept a photograph of the second exchange rather than the finish. It showed an important part of the race that he had once thought nobody would notice.`,
], [
  q('detail', 'Why did the teacher choose Daniel for the second section?', ['He was unable to run in front of a crowd.', 'He had asked to avoid competing against Luis.', 'His ability to exchange the baton suited that position.', 'His individual running time was the slowest.'], 2, 'ダニエルは前後の走者と正確にバトンを受け渡すことができ、中間のつなぎ役に向いていたためです。', 'p2', 'receive the baton smoothly from a slower runner and pass it accurately to the next person'),
  q('detail', 'What caused trouble during the first practice race?', ['Daniel began moving before his teammate could reach him.', 'Luis dropped the baton at the finish line.', 'The third runner refused to practice exchanges.', 'The teacher changed the running order during the race.'], 0, 'ダニエルが早く走り出しすぎ、最初の走者が追いついて渡すのに苦労しました。', 'p3', 'he started too early and left the first runner struggling to reach him'),
  q('inference', 'What does the improved practice time suggest?', ['Personal records are unrelated to any kind of race.', 'Running the last section is always the easiest role.', 'A relay team improves only by changing its members.', 'Better coordination can help even without faster individual running.'], 3, '個人記録を更新しなくても、受け渡しがよくなるとチーム全体のタイムは改善しました。', 'p4', 'finished faster even though Daniel did not set a personal record'),
  q('main-idea', 'How did Daniel’s view change?', ['He decided that winning should never matter.', 'He came to value a contribution beyond the most visible role.', 'He concluded that individual skill was unnecessary.', 'He believed photographs were more useful than practice.'], 1, '目立つ最終走者だけでなく、チームをつなぐ自分の役割にも価値を見いだすようになりました。', 'p4', 'an important part of the race that he had once thought nobody would notice'),
], [v('relay', 'リレー競走'), v('exchange', '受け渡し・交換'), v('coordination', '動きを合わせること・連携')]),

make('2級', 'food', 'What the Recipe Left Out', [
  `Mika wanted to make the flatbread that her grandfather baked for family lunches. He gave her a page listing flour, water, salt, and oil. Beside the water, he had written “about one cup.” Mika followed the page carefully, but her first dough was too stiff to spread easily. She thought she had failed to measure the ingredients correctly.`,
  `When she visited her grandfather, she brought her measuring cup. His usual cup was smaller, yet the dough he made felt softer than hers. Watching him closely, Mika noticed that he added more water after mixing. He had not written down this step because he did it without thinking. He also covered the dough and left it for a while before shaping it.`,
  `Mika asked him to pause and explain what he was looking for. He showed her how the mixture changed as he worked with it. Instead of only saying “add water,” he described the feel he wanted and demonstrated it with a small piece. Mika wrote down the resting time and measured the amount of water he used that day. She kept the numbers but added descriptions beside them.`,
  `At home, Mika's second attempt was closer to her grandfather's bread. It was not exactly the same, and she still needed practice. However, she could now recognize which stage needed attention instead of treating every disappointing result as a measuring error. She sent her cousin the revised recipe with a short video of the dough being shaped. The cousin said the video explained something the ingredient list could not. Mika understood that a familiar task can contain small decisions that an experienced person no longer notices, even when those decisions are important to a beginner.`,
], [
  q('detail', 'What did Mika initially think caused the problem?', ['She had measured the ingredients incorrectly.', 'Her grandfather had used a different kind of oil.', 'The recipe contained too many written instructions.', 'She had shaped the bread before adding flour.'], 0, '最初は、材料の量を正しく測れなかったためだと思いました。', 'p1', 'She thought she had failed to measure the ingredients correctly'),
  q('detail', 'Which action was missing from the original recipe?', ['Putting flour in the mixture.', 'Using a cup to measure water.', 'Adding more water after the initial mixing.', 'Serving the bread at family lunches.'], 2, '祖父は混ぜた後にも水を加えていましたが、習慣になっていて書き忘れていました。', 'p2', 'he added more water after mixing'),
  q('inference', 'Why did Mika keep both measurements and descriptions?', ['She wanted readers to choose only the shortest instructions.', 'She needed to record amounts and signs of the desired texture.', 'Her grandfather wanted her to remove the demonstration.', 'She believed numbers could guarantee identical results every time.'], 1, '量に加えて、生地がどんな状態になるべきかも分かるようにするためです。', 'p3', 'She kept the numbers but added descriptions beside them'),
  q('main-idea', 'What does the story suggest about teaching a familiar skill?', ['Beginners should avoid using written instructions.', 'Experienced people always know which details they leave out.', 'Videos are unnecessary when ingredients are measured.', 'Important decisions may need to be made explicit for a beginner.'], 3, '熟練者が無意識にしている小さな判断でも、初心者には説明する必要があるという話です。', 'p4', 'small decisions that an experienced person no longer notices'),
], [v('dough', 'パンなどを焼く前の生地'), v('ingredient', '材料・原料'), v('attempt', '試み・やってみること')]),

make('2級', 'relationships', 'Before Offering an Answer', [
  `After school, Omar met his friend Hana at a café. She had recently joined the art club and was upset about a group project. Before she had finished explaining, Omar suggested changing groups, speaking to the teacher, and refusing to do extra work. He expected her to feel better because he had offered several possible solutions. Instead, she became quiet.`,
  `Omar asked whether all his ideas were bad. Hana said that the problem was not simply finding a solution. She already intended to speak to the group leader, but she was worried about sounding unkind. She had wanted to explain what had happened and sort out her feelings before deciding what to say. Omar had answered a question she had not yet asked.`,
  `He put away his phone and invited her to continue. This time, he asked short questions about the situation rather than immediately recommending an action. He learned that one member had missed a deadline because of a family problem. Hana wanted the work to be shared fairly, but she did not want to ignore that difficulty. The extra information changed Omar's understanding of the disagreement.`,
  `When Hana finished, Omar asked whether she wanted to practice the conversation with him. She accepted, and they tried a few ways of raising the issue. They did not agree on every word, but the exercise helped her decide how to begin. Later, Omar realized that listening had not meant doing nothing. It had helped him discover what kind of support his friend actually wanted. He also understood that asking first would not always produce the same answer. On another day, Hana might want a direct suggestion. The useful habit was to find out rather than assume.`,
], [
  q('detail', 'What did Omar expect when he offered several solutions?', ['Hana would ask him to join the art club.', 'The teacher would solve the problem immediately.', 'He would learn every detail of the disagreement.', 'Hana would feel better because he had suggested actions.'], 3, '解決策をいくつか示せば、ハナの気持ちが楽になると期待していました。', 'p1', 'He expected her to feel better'),
  q('detail', 'What was Hana particularly worried about?', ['Finding a café where they could talk.', 'Sounding unkind when she raised the issue.', 'Choosing a completely different club.', 'Forgetting the deadline for her own work.'], 1, 'リーダーに相談するつもりではありましたが、きつい言い方にならないかを心配していました。', 'p2', 'she was worried about sounding unkind'),
  q('inference', 'Why did learning about the missed deadline matter?', ['It showed that the group no longer needed to finish its work.', 'It proved that Hana should never discuss the unequal workload.', 'It revealed a difficulty that Hana wanted to take into account.', 'It explained why Omar had been chosen as the group leader.'], 2, '欠席した人の家庭事情を知り、ハナが公平さと相手への配慮を両立させたいことが分かりました。', 'p3', 'she did not want to ignore that difficulty'),
  q('main-idea', 'What useful habit did Omar learn?', ['Ask what support is wanted before assuming how to help.', 'Avoid giving suggestions even when someone requests them.', 'Agree with a friend’s view before hearing the whole story.', 'Treat a practice conversation as a guaranteed solution.'], 0, 'その時に必要な支え方を確かめてから助けることが大切だと学びました。', 'p4', 'The useful habit was to find out rather than assume'),
], [v('deadline', '締め切り'), v('recommend', '勧める'), v('assume', '確かめずにそうだと思う')]),

make('2級', 'media', 'The Photograph Outside the Frame', [
  `For the school newspaper, Leo photographed the courtyard just after the lunch bell. He stood beside the library, where several students were sitting with open books. His photograph showed a peaceful scene. The editor proposed the caption “Students choose reading over outdoor games.” Leo liked the sentence because it made his picture seem to tell an interesting story.`,
  `Before sending the page to print, Leo returned to the courtyard. From another doorway, he could see a group playing basketball beyond the edge of his photograph. A long table of students eating lunch was also missing from the image. The people reading had not been placed there for the camera, but they were only part of what was happening.`,
  `Leo showed the editor a wider photograph. She said the original picture was still useful: it clearly showed a place where students could read outside. However, the proposed caption made a comparison that the picture could not support. Neither of them had counted how many students chose each activity, and one lunch break would not necessarily describe their usual preferences.`,
  `They kept the first photograph and changed the caption to describe the readers near the library on that particular day. They also removed a sentence claiming that outdoor games were becoming less popular. Leo worried that the page now sounded less exciting, but a classmate said it had helped her discover a quiet place to sit. The photograph did not need a large claim to be worthwhile. Leo kept taking carefully framed pictures, since a newspaper page could not show everything. He became more careful, though, about the difference between selecting a scene and presenting that selection as evidence about everyone.`,
], [
  q('detail', 'What did Leo see when he returned to the courtyard?', ['The readers had moved inside because of rain.', 'The basketball court had been removed.', 'Other activities had taken place outside his original frame.', 'The editor had asked students to pose with books.'], 2, '写真の外側にはバスケットボールや昼食中の生徒もいて、読書だけが行われていたわけではありませんでした。', 'p2', 'A long table of students eating lunch was also missing from the image'),
  q('inference', 'Why was the first proposed caption unsuitable?', ['It compared preferences without enough supporting evidence.', 'It described a place that did not exist.', 'It used the library’s name without permission.', 'It failed to identify every student in the photograph.'], 0, '人数を数えておらず、一日の写真だけで読書と運動の人気を比較する根拠もなかったためです。', 'p3', 'made a comparison that the picture could not support'),
  q('detail', 'How did the newspaper finally use the photograph?', ['It replaced the readers with a picture of a classroom.', 'It presented the scene as proof that games were unpopular.', 'It printed the original caption beside the wider photograph.', 'It described the specific people, place, and occasion shown.'], 3, '元の写真を残し、その日に図書室近くで読んでいた生徒という、確認できる場面の説明に変えました。', 'p4', 'changed the caption to describe the readers near the library on that particular day'),
  q('main-idea', 'What did Leo learn?', ['Every photograph should include the entire location.', 'An honest image can still be used to support an unjustified claim.', 'A picture is useful only when it reveals a major trend.', 'Choosing a camera position necessarily makes a photograph false.'], 1, '写真の場面自体は本物でも、それを全員の好みや傾向の証拠として扱うと行き過ぎることがあると学びました。', 'p4', 'the difference between selecting a scene and presenting that selection as evidence about everyone'),
], [v('caption', '写真などに添える説明文'), v('frame', '写真に写る範囲・枠'), v('claim', '主張・言い分')]),

make('2級', 'logic-reasoning', 'A Rule and Its Reverse', [
  `At a fictional school festival, students used colored stickers to organize displays of model buildings. The rule was simple: every model containing a working light had to carry a red sticker. Red stickers were also allowed on models without lights. A student named Emi was asked to check whether the rule had been followed before the displays opened.`,
  `Emi first collected all the models with red stickers and looked for lights inside them. When she found a model with a red sticker but no light, she thought she had discovered a mistake. Her teacher asked her to read the rule again. The rule told her what a model with a working light needed. It did not say that every model with a red sticker must contain one.`,
  `Together, they imagined four possibilities: a light with a red sticker, a light without one, no light with a red sticker, and no light without one. Only the second possibility broke the rule. Emi now knew what she needed to search for. She examined the models without red stickers to see whether any contained working lights. She found one, and its maker added the required sticker.`,
  `Later, Emi wrote a sentence in her notebook: “If a model has a light, it needs a red sticker” is different from “If it has a red sticker, it needs a light.” Changing the order of the two parts had changed the claim. She also realized that looking at examples which satisfied a rule was not always the best way to check it. A model with both a red sticker and a light could show that one maker had followed the instruction. It could not tell her whether another model elsewhere had broken it. Once she knew exactly what a violation would look like, her search became much more useful.`,
], [
  q('detail', 'Which model was allowed under the festival rule?', ['A model with a working light but no red sticker.', 'A model with no light and a red sticker.', 'Only models with working lights.', 'Only models with stickers of two colors.'], 1, '赤いシールはライトのない模型にも付けてよいと明示されています。', 'p1', 'Red stickers were also allowed on models without lights'),
  q('detail', 'What was wrong with Emi’s first judgment?', ['She had forgotten to turn off the lights.', 'She assumed every model had the same maker.', 'She treated the rule’s reverse as if it were also required.', 'She checked models before the festival had ended.'], 2, '「ライトがあれば赤いシールが必要」を「赤いシールがあればライトが必要」と逆向きに読んでしまいました。', 'p2', 'It did not say that every model with a red sticker must contain one'),
  q('inference', 'Why did Emi examine models without red stickers?', ['One of them could contain a light and therefore violate the rule.', 'All of them had already been shown to break the rule.', 'The teacher wanted every sticker replaced with a blue one.', 'Models without stickers were the only ones visitors could see.'], 0, '赤いシールがない模型にライトがあれば、まさに規則違反になるためです。', 'p3', 'Only the second possibility broke the rule'),
  q('main-idea', 'What made Emi’s search more useful?', ['Finding several attractive models to display together.', 'Assuming the reverse of every instruction was true.', 'Checking only examples that clearly followed the rule.', 'Identifying the exact situation that would count as a violation.'], 3, '何が規則違反になるのかを明確にして、その状態を探すようにしたことが役立ちました。', 'p4', 'Once she knew exactly what a violation would look like'),
], [v('violation', '規則などに反すること・違反'), v('reverse', '逆・反対の向き'), v('satisfy', '条件などを満たす')]),

make('準1級', 'arts-culture', 'The Ending That Changed in the Camera', [
  `In the fictional novel The Last Window, a woman returns to the house where she grew up and finds a sealed letter on a table. The final page describes her reaching towards it but never reveals whether she opens it. Mira, a student filmmaker adapting the novel, initially believed that respecting the author meant reproducing this ending as literally as possible. Her first version therefore ended with an actor extending her hand and the screen suddenly going dark.`,
  `The written passage, however, did more than report a physical action. It moved between the woman's memories, her doubts about the letter, and her awareness of the sounds outside. The reader could remain inside these thoughts while the hand was still approaching the envelope. On screen, the same movement lasted only a few seconds. Viewers at a private screening did not describe a difficult emotional choice. Several assumed that a technical fault had interrupted the film just before the story was resolved.`,
  `Mira considered adding a voice that would read the final page aloud. That would preserve much of the language, but she felt it would repeat ideas already expressed through earlier scenes. She also considered showing the letter being opened, which would provide a clear physical conclusion while removing the uncertainty that had attracted her to the novel. Neither option was automatically wrong. Each would preserve some features of the source and give up others. The problem was deciding which features mattered most to her interpretation.`,
  `She eventually changed the sequence. The woman placed her hand beside the letter, listened to a familiar sound from the garden, and then looked towards the window. Mira held the shot long enough for the stillness to feel deliberate. The film ended without another movement. These actions were not a direct copy of the final sentence, but they gave viewers time to recognize that an unresolved decision, rather than a missing technical conclusion, was the point of the scene.`,
  `A classmate objected that the new ending was less faithful because it introduced a gesture the author had not described. Mira took the criticism seriously. A change could not be justified merely by calling it creative. She explained which tension she was trying to preserve and showed how the earlier scenes prepared for it. Another filmmaker might reasonably choose a different emphasis. What mattered was that the adaptation's choices could be discussed in relation to the source, rather than defended as personal preference alone.`,
  `The exercise changed Mira's understanding of fidelity. Keeping every visible action unchanged can alter an audience's experience when the means of telling the story change. Conversely, changing an action can sometimes preserve an important relationship between uncertainty, memory, and choice. This does not make accuracy irrelevant or allow any alteration to count as respect for the original. It makes fidelity a reasoned commitment: an adapter needs to identify what is being carried across, what is being transformed, and why the transformation serves a coherent reading of the work.`,
], [
  q('detail', 'How did some viewers understand Mira’s first ending?', ['As proof that the character had destroyed the letter.', 'As an interruption caused by a technical problem.', 'As an explanation of every memory in the novel.', 'As a scene taking place after the letter had been read.'], 1, '最初の映像では、未解決の感情的な選択ではなく、故障で結末直前に映像が切れたと受け取った人がいました。', 'p2', 'a technical fault had interrupted the film'),
  q('inference', 'Why was copying the hand movement insufficient?', ['The actor had never read the original novel.', 'Written stories cannot describe physical gestures accurately.', 'The letter had a different meaning in every earlier scene.', 'The prose used inner thoughts to give the brief action greater duration and significance.'], 3, '文章は記憶や疑念をたどる時間を作れますが、同じ手の動きだけを映すと数秒で終わり、その働きが失われました。', 'p2', 'The reader could remain inside these thoughts while the hand was still approaching the envelope'),
  q('purpose', 'Why did Mira explain the tension she wanted to preserve?', ['To show a reasoned connection between her changes and the source.', 'To prove that no other interpretation could be reasonable.', 'To avoid considering the classmate’s criticism.', 'To claim that creative choices need no justification.'], 0, '追加した動作を単なる好みとしてではなく、原作のどんな緊張関係を保つための判断なのか説明しました。', 'p5', "the adaptation's choices could be discussed in relation to the source"),
  q('main-idea', 'What view of fidelity does the passage support?', ['Unchanged physical actions guarantee an unchanged audience experience.', 'An adaptation should always replace the original ending.', 'Faithfulness requires explaining what a transformation preserves and why.', 'Accuracy has little value when a story changes its medium.'], 2, '忠実さを、何を受け継ぎ、なぜ表現を変えるのかを根拠付きで考える姿勢として捉えています。', 'p6', 'identify what is being carried across, what is being transformed, and why'),
], [v('fidelity', '原作などに対する忠実さ'), v('adaptation', '別の媒体などに作り替えた作品・翻案'), v('coherent', '筋が通った・一貫した')]),

make('準1級', 'sports', 'The Player Outside the Highlight', [
  `When the fictional Eastbank basketball team won a close match, its school newspaper featured a photograph of the winning shot. The scorer, Jalen, deserved the attention: he had controlled a difficult pass and scored under pressure. Yet his teammate Sora, who had not scored during the final quarter, recognized several decisions behind that moment which the photograph could not show. She had moved away from the basket, taking a defender with her and opening the space into which Jalen received the ball.`,
  `This did not mean that Sora alone had created the victory, or that scoring was somehow a less valuable contribution. The pass had to be accurate, the shot had to succeed, and the other players had to position themselves effectively. A single outcome was produced by linked actions. Giving all the credit to the last visible action simplified that process, but giving it all to an unnoticed earlier action would merely replace one oversimplification with another.`,
  `The difficulty became clearer when the team watched a recording of an earlier defeat. Sora had made a similar movement, but the following pass went outside the court. No successful shot appeared in the statistics, and her movement attracted little comment. The coach asked whether the different outcome necessarily made her earlier decision worse. The players agreed that it did not. A sensible action could be followed by a mistake elsewhere, just as a poor decision could occasionally be rescued by an exceptional shot.`,
  `However, judging decisions without their outcomes also had limits. Sora could not claim that every unsuccessful movement had been useful simply because its intended effect was invisible. The coach asked the players to identify observable details: where defenders were standing, what passing options were available, and whether the movement actually changed those options. They paused the recording before learning the result and discussed what a player could reasonably have known at that moment. This did not produce certainty, but it made their explanations more specific.`,
  `For the next match, each player chose one aspect of decision making to examine afterwards. Jalen focused on whether he noticed a teammate in a better position. Sora focused on whether her movement created space without blocking someone else's path. They still recorded points and cared about winning. The additional questions were meant to connect those outcomes to actions the players could work on, rather than turn the review into a competition over who had contributed in the least visible way.`,
  `The distinction mattered to Sora because recognition and improvement were not identical goals. A photograph could celebrate a memorable moment without serving as a complete explanation of the match. A useful review needed a wider view, including failed sequences and information available before the result was known. The team could acknowledge outstanding individual skill while also recognizing how that skill depended on surrounding decisions. Understanding a performance meant resisting both the temptation to explain everything through the final score and the temptation to dismiss the score entirely.`,
], [
  q('detail', 'What did Sora do before the winning shot?', ['She took the final pass away from Jalen.', 'She blocked her teammate’s route to the basket.', 'She drew a defender away and created space.', 'She replaced the player who had scored earlier.'], 2, 'ゴールから離れる動きで守備者を引きつけ、ジェイレンがパスを受ける空間を作りました。', 'p1', 'taking a defender with her and opening the space'),
  q('inference', 'What does the earlier defeat help illustrate?', ['A decision’s quality cannot always be inferred directly from the final outcome.', 'The same movement should be repeated in every situation.', 'Unsuccessful passes are more useful than successful shots.', 'Statistics prove that unnoticed actions are always superior.'], 0, '同様に適切な動きでも、その後のパスの失敗で得点にならない場合があり、結果だけで先の判断を評価できないと示しています。', 'p3', 'A sensible action could be followed by a mistake elsewhere'),
  q('purpose', 'Why did the coach ask for observable details?', ['To guarantee that every disputed decision had one certain explanation.', 'To replace every discussion with a count of baskets.', 'To prevent players from examining unsuccessful sequences.', 'To make claims about hidden contributions concrete and assessable.'], 3, '見えにくい貢献を言い張るだけにならないよう、位置や選択肢の変化という具体的な根拠を求めました。', 'p4', 'it made their explanations more specific'),
  q('main-idea', 'What approach to performance review does the passage recommend?', ['Treat the last successful action as the only meaningful contribution.', 'Consider results alongside the linked decisions that produced them.', 'Reward unnoticed actions regardless of their effect on the game.', 'Avoid discussing individual skill because teamwork determines everything.'], 1, '結果や個人の技術を大切にしつつ、それを生んだ複数の判断や連携も調べる姿勢を勧めています。', 'p6', 'recognizing how that skill depended on surrounding decisions'),
], [v('observable', '観察して確かめられる'), v('oversimplification', '複雑なことを単純化しすぎること'), v('sequence', '連続した出来事・順序')]),

make('準1級', 'food', 'More Than What Was in the Cup', [
  `For a small gathering in the fictional town of Merrow, Ellis prepared two kinds of tea. One came in a plain packet from a nearby shop. The other was a gift from a friend who had visited a small producer and described the care taken in preparing it. Ellis expected the second tea to be everyone's favorite. Curious about whether the story mattered, he served both without showing their packets and asked his guests which they preferred.`,
  `The answers were mixed. Two guests preferred the first tea, one preferred the second, and another said that the difference was too slight to choose confidently. Ellis was surprised. He had enjoyed the gift especially strongly when drinking it alone. One guest joked that he had been paying attention to the story rather than the tea. Ellis wondered whether the pleasure he remembered had therefore been somehow false.`,
  `The conversation became more interesting when he explained the gift's background. A guest pointed out that there were several different questions at stake. If Ellis claimed that everyone could identify the second tea by its flavor, the tasting gave him little support. But that claim was different from saying that the gift, its connection to his friend, and the circumstances in which he drank it had made the experience more meaningful to him. A preference for an experience was not necessarily a judgment about a liquid considered in isolation.`,
  `This distinction did not excuse misleading descriptions. A seller who invented an attractive origin story would be asking customers to value something that had not happened. Claims about ingredients or production methods also needed evidence; a pleasant feeling could not establish their truth. Ellis's friend's account, however, was being discussed as part of a personal gift, not as proof that the tea had superior qualities which every drinker should detect. The group could recognize that difference without deciding that background information was either always essential or always irrelevant.`,
  `Ellis then considered the limits of his little comparison. He had used the same cups and had not shown the packaging, but he had not measured every detail of preparation. A few guests at one evening gathering could not represent everyone's preferences. He could describe what those people had chosen under those conditions, not announce a ranking that would settle the value of either tea. Even a carefully controlled comparison would still need a clear account of the question it was designed to answer.`,
  `At the end of the evening, Ellis served the gift again and told his guests why receiving it had mattered to him. Nobody was asked to change a preference or agree that it tasted better. The first packet was also left on the table. The evening had not shown that sensory judgment was useless, nor that a good story could justify any claim about a product. It had shown Ellis the importance of keeping distinct kinds of value separate enough to discuss honestly: what was in the cup, what could be established about its origin, and what the occasion meant to the people drinking it.`,
], [
  q('detail', 'Why was Ellis surprised by the first tasting?', ['Every guest recognized the tea’s producer immediately.', 'The guests refused to try tea without seeing its packet.', 'His friend admitted that the gift had come from another source.', 'The gift was not clearly preferred by the group.'], 3, '自分は贈り物のお茶を特に気に入っていましたが、参加者の好みは分かれ、明確な一番にはなりませんでした。', 'p2', 'The answers were mixed'),
  q('inference', 'What distinction does the guest make about Ellis’s enjoyment?', ['Enjoyment proves that a product’s origin story is true.', 'A meaningful experience is different from a claim about flavor alone.', 'Personal gifts should never be compared with ordinary purchases.', 'Background information affects only people who cannot taste differences.'], 1, '友人とのつながりを含めた体験の価値と、液体の味そのものに関する比較は別の問いだと説明しています。', 'p3', 'A preference for an experience was not necessarily a judgment about a liquid considered in isolation'),
  q('detail', 'What limitation does Ellis recognize in his comparison?', ['He had given every guest a different story about the tea.', 'The cups had shown which packet each tea came from.', 'Its few participants and particular conditions limited what he could conclude.', 'It had established the preferences of people who were not present.'], 2, '少人数・一度の会で、準備条件もすべて測定しておらず、一般的な順位までは結論できないと理解しました。', 'p5', "A few guests at one evening gathering could not represent everyone's preferences"),
  q('main-idea', 'What is the central lesson of the passage?', ['Different kinds of value and factual claims should be distinguished rather than confused.', 'A compelling personal story is sufficient evidence for any claim of quality.', 'Products should be judged only after every detail of their origin is forgotten.', 'A tasting with hidden labels can settle every question about value.'], 0, '味、確かめられる来歴、個人的な思い入れを混同せず、それぞれについて正直に話すことが主題です。', 'p6', 'keeping distinct kinds of value separate enough to discuss honestly'),
], [v('sensory', '感覚に関わる'), v('in isolation', '他の事情から切り離して'), v('misleading', '誤解を招く')]),

make('準1級', 'relationships', 'The Favor Without an Agreement', [
  `When the fictional illustrator Ren needed somewhere to finish a large school display, his friend Tessa offered the spare room above her family's shop. Ren accepted gratefully. The arrangement saved him several long journeys, and Tessa seemed pleased to help. They discussed when he could enter the room and where he could leave his materials, but neither mentioned any obligation beyond keeping the space tidy and returning the key.`,
  `Several weeks later, Tessa asked Ren to design a poster for an event at the shop. Ren said he could not complete it before her deadline because he was preparing for an examination. Tessa replied that she had assumed he would help after everything she had done for him. Ren was upset, partly because he valued the earlier favor and partly because the request now felt like a bill whose amount and payment date had never been stated.`,
  `The disagreement was not simply between one generous person and one ungrateful person. Tessa had given up a useful space and believed that mutual help was part of their friendship. Ren also believed in helping friends, but he had not understood the room as an exchange for work on a future occasion. Both could sincerely value reciprocity while imagining different limits on what it required. Their shared general principle had concealed a practical difference in expectations.`,
  `At first, Ren considered agreeing to make the poster to end the discomfort. He then realized that doing so would leave the underlying misunderstanding untouched. Instead, he thanked Tessa specifically for the room and explained the preparation he still needed to finish. He offered to help with a later event but said that he could not promise work whenever it was requested. Tessa admitted that she had treated her expectation as obvious and had taken his refusal as a judgment on how much her help mattered.`,
  `They did not turn every future favor into a written contract. Such an arrangement would have felt strange to both of them. They did, however, agree to state conditions when those conditions would affect whether someone could accept. A temporary loan of equipment needed a return date. Help that depended on receiving another service in exchange should be described that way. When a favor was offered freely, appreciation could still be expected without assuming an unlimited right to another person's time.`,
  `The conversation did not remove every possibility of disappointment from their friendship. Ren might sometimes underestimate the effort Tessa had made, and she might sometimes ask for more than he could offer. What changed was their ability to discuss those differences without immediately treating them as evidence of bad character. Gratitude, obligation, and availability were connected, but they were not identical. A friendship could include an expectation of mutual care while still leaving room for a particular request to be declined and for the reasons behind that refusal to be heard.`,
], [
  q('detail', 'What had Ren and Tessa explicitly agreed before he used the room?', ['Ren would design every future shop poster.', 'Ren would repay the loan before his examination.', 'He would keep it tidy and return the key, alongside arrangements for access and storage.', 'Tessa would decide which school tasks he should finish first.'], 2, '入室や道具の置き場所に加えて、整理整頓と鍵の返却は話し合いましたが、将来のポスター制作までは約束していませんでした。', 'p1', 'neither mentioned any obligation beyond keeping the space tidy and returning the key'),
  q('inference', 'Why could both friends value reciprocity yet disagree?', ['They attached different practical expectations to the same general principle.', 'Only one of them understood that the room had been useful.', 'They had deliberately concealed a written contract.', 'They disagreed about whether the shop event would take place.'], 0, '助け合いを大切にする点は共通でも、それがいつ・どこまでの応諾を求めるかについて理解が違っていました。', 'p3', 'imagining different limits on what it required'),
  q('purpose', 'Why did Ren avoid agreeing merely to end the discomfort?', ['He wanted Tessa to stop offering help to anyone.', 'He believed gratitude should never be expressed directly.', 'He planned to avoid discussing the room again.', 'The unresolved expectations could otherwise continue to cause problems.'], 3, 'その場を収めるためだけに引き受けても、根本の期待のずれは残ると気づいたためです。', 'p4', 'doing so would leave the underlying misunderstanding untouched'),
  q('main-idea', 'What view of friendship does the passage support?', ['Gratitude requires accepting every request from someone who has helped.', 'Mutual care can coexist with clear expectations and the ability to decline a request.', 'All favors become meaningless unless a contract specifies their value.', 'A disagreement about availability reliably reveals a person’s character.'], 1, '助け合いや感謝を保ちながら、条件を確かめたり、事情によって個別の依頼を断ったりすることは両立するとしています。', 'p6', 'leaving room for a particular request to be declined'),
], [v('reciprocity', '互いに与えたり助けたりする関係・互恵性'), v('obligation', '義務・果たすべきこと'), v('availability', '時間などの都合がつくこと')]),

make('準1級', 'media', 'The Interview That Could Not Fit', [
  `For a fictional local magazine, student reporter Aya interviewed a craft worker about a proposed redevelopment near his workshop. The conversation lasted an hour, but the printed article had room for only a few short quotations. At first, Aya thought that fairness would be easy: she would choose the clearest sentences and reproduce each one exactly. As long as the words were accurate, she assumed, the account would be accurate too.`,
  `Reading her notes, she found a forceful statement near the beginning: the craft worker had said he wanted the project stopped. Much later, however, he explained that he might support a revised proposal if workshops were given affordable replacement space. If Aya printed the first statement alone, the quotation would be exact but the impression of an unconditional refusal would be misleading. His position had not necessarily changed during the interview. The longer conversation had revealed a condition that the short statement did not express.`,
  `Aya drafted a paragraph explaining both the objection and the condition. She then faced a different problem. The interviewee had repeated a claim that every workshop would have to close, but the planning document she obtained did not support that statement. It described several different arrangements for different buildings. Respecting his view did not require presenting every factual claim he made as established. Aya could report his concern, explain what the document actually said, and make clear where uncertainty remained.`,
  `She briefly considered publishing the complete recording and letting readers decide for themselves. That would preserve much more of the exchange, but it would not remove the need for editorial judgment. Readers would still need to find the relevant passages, understand references to documents, and distinguish a confident assertion from supported information. Some private details in the conversation were also irrelevant to the public issue. Providing more material could aid scrutiny, but volume alone would not make the account fair or understandable.`,
  `Before publication, Aya checked the wording of the selected quotations against the recording and confirmed that her explanation of the interviewee's condition was accurate. She did not offer him control over the article's conclusions. The magazine's editor explained that correcting a misquotation and granting a subject permission to remove inconvenient evidence were different actions. Aya also kept a note of which passages had been omitted and why, so that she could answer questions about her selection later.`,
  `The final article was shorter than the interview and necessarily incomplete. Nevertheless, it represented the craft worker's position more accurately than a collection of dramatic, word-perfect quotations would have done. Aya had learned that selection cannot be eliminated from reporting; even a complete recording begins and ends somewhere. The responsibility is to select in ways that preserve relevant conditions, distinguish claims from evidence, and remain open to correction. Fairness depends not on pretending that no choices were made, but on making those choices defensible.`,
], [
  q('inference', 'Why could an exact quotation still mislead readers?', ['The interviewee had forbidden any use of his recorded words.', 'It could omit a condition essential to understanding his position.', 'A quotation is accurate only when it includes an entire interview.', 'The magazine had already decided to support the project.'], 1, '「中止してほしい」だけでは、条件次第で改訂案を支持する可能性を落としてしまうためです。', 'p2', 'the impression of an unconditional refusal would be misleading'),
  q('detail', 'How did the planning document affect Aya’s work?', ['It confirmed that every workshop would close under identical arrangements.', 'It required her to remove all of the interviewee’s concerns.', 'It showed that one factual claim needed qualification rather than repetition as fact.', 'It proved that the interviewee had deliberately changed his position.'], 2, '工房ごとに異なる対応が書かれており、「すべて閉鎖」という発言をそのまま確定事項として扱えないと分かりました。', 'p3', 'the planning document she obtained did not support that statement'),
  q('purpose', 'Why does the passage discuss publishing the entire recording?', ['To examine why more material does not automatically remove editorial responsibilities.', 'To establish that readers should never be given access to source material.', 'To show that private details are always more important than public questions.', 'To argue that a reporter may alter quotations when space is limited.'], 0, '全文を出しても、関連箇所の案内、根拠の区別、不要な私的情報への配慮などの判断は残ると検討しています。', 'p4', 'it would not remove the need for editorial judgment'),
  q('main-idea', 'What does Aya learn about fair reporting?', ['Avoiding all selection is the only reliable standard of fairness.', 'The most dramatic exact quotations necessarily give the fullest picture.', 'Interview subjects should decide which conclusions may be published.', 'Selections should preserve relevant context and be supported by reasons that can be examined.'], 3, '選択をなくすことではなく、重要な条件や根拠を残し、後から説明・訂正できる選び方をすることが大切だと学びました。', 'p6', 'making those choices defensible'),
], [v('assertion', '主張・断言'), v('scrutiny', '注意深い検討・精査'), v('defensible', '根拠を示して正当化できる')]),

make('準1級', 'logic-reasoning', 'The Dry Day in the Notebook', [
  `During a fictional school discussion, Tom claimed that the local bus was late only on rainy days. He had begun keeping a notebook after arriving late for several morning classes, and every delay he remembered recording had coincided with rain. His friend Lila asked whether he meant that rain sometimes contributed to delays, that delays were more common in rain, or that a delay never occurred on a dry day. Tom answered that he meant the last of these.`,
  `Lila then showed him a dated message from a morning when she had waited twenty minutes beyond the published arrival time. The message described clear skies. If the bus really was late and the relevant day was dry, her example would conflict with Tom's claim. He could not settle the disagreement merely by producing ten more rainy delays. Those examples could all be consistent with his claim while leaving the dry-day case unexplained.`,
  `However, Lila's message was not automatically decisive simply because it looked like a counterexample. They first checked whether she had been waiting for the same bus service and whether the timetable she used was current. A mistaken time or a different route would make the comparison irrelevant. They also needed an agreed meaning of “late”: a bus arriving two minutes after its expected time might be classified differently from one arriving twenty minutes afterwards. Clear definitions mattered before either person counted the evidence.`,
  `The route and timetable matched, and they agreed that the delay exceeded the threshold they had chosen. Tom next suggested that it might have been raining somewhere else along the route. That possibility was worth checking, but he recognized a danger in repeatedly expanding the condition after each objection. If “rainy day” eventually meant any rain anywhere that might possibly affect a journey, the claim could become too vague to test. A condition should clarify the claim rather than protect it from every imaginable challenge.`,
  `The route's weather records confirmed dry conditions that morning, and a service notice reported a broken-down vehicle. Tom revised his statement: rain could be one cause of delay, but it was not a necessary condition for every delay. This revision did not tell them how important rain was compared with other causes. Answering that question would require a different investigation, including information about ordinary journeys as well as late ones. His notebook, which recorded problems that had attracted his attention, could not by itself provide that comparison.`,
  `Tom was initially embarrassed about giving up his original claim. Lila pointed out that he now had a more precise question and a clearer idea of the evidence it needed. Their discussion illustrated two responsibilities that belong together: a broad claim should be open to a genuine counterexample, and an apparent counterexample should itself be checked carefully. Neither collecting only supporting cases nor accepting every surprising objection is sufficient. Better reasoning begins with knowing what is being claimed, what would count against it, and how the reliability of that evidence can be examined.`,
], [
  q('detail', 'Which claim did Tom initially say he intended?', ['Rain was the most frequent cause of delays on every route.', 'Rain could contribute to delays without being necessary.', 'A delay never occurred when the relevant day was dry.', 'Every rainy day caused every bus to arrive late.'], 2, '選択肢として示された三つのうち、最後の「乾いた日に遅延は起きない」という主張を選びました。', 'p1', 'Tom answered that he meant the last of these'),
  q('inference', 'Why would ten more rainy delays not settle the disagreement?', ['Supporting instances would not remove a genuine conflicting dry-day case.', 'Ten examples are always too few to support any kind of claim.', 'Rainy delays were unrelated to the bus service Tom used.', 'A dated message is necessarily more accurate than a notebook.'], 0, '雨の日の遅延が増えても、「乾いた日の遅延」という反例が本当なら、元の普遍的な主張との矛盾は解消しません。', 'p2', 'leaving the dry-day case unexplained'),
  q('purpose', 'Why did they check the route and timetable before drawing a conclusion?', ['To redefine rain so that Tom’s claim could never be challenged.', 'To prove that all published arrival times were unreliable.', 'To replace the disputed delay with a more convenient example.', 'To establish whether the apparent counterexample was relevant and accurately described.'], 3, '別の便や古い時刻表なら反例にならないため、同じ条件で正しく記録された遅延か確かめました。', 'p3', 'A mistaken time or a different route would make the comparison irrelevant'),
  q('main-idea', 'What standard of reasoning does the passage favor?', ['Protect a general claim by broadening its conditions whenever it is questioned.', 'Remain open to counterexamples while checking their definitions, relevance, and reliability.', 'Reject a general claim whenever any surprising statement is reported.', 'Use a collection of memorable problems to determine the frequency of every cause.'], 1, '反例を受け入れる姿勢と、その反例の定義・関連性・信頼性を確認する慎重さの両方が必要だとしています。', 'p6', 'a broad claim should be open to a genuine counterexample, and an apparent counterexample should itself be checked carefully'),
], [v('counterexample', '一般的な主張に反する具体例・反例'), v('threshold', '判定の境目となる基準'), v('necessary condition', '必要条件')]),
];
